import{_ as a,o as e,c as s,a as n}from"./app.CYXXef1p.js";const h=JSON.parse('{"title":"Routing Decision Matrix: Task Category Logic","description":"","frontmatter":{},"headers":[],"relativePath":"reference/ROUTING_DECISION_MATRIX.md","filePath":"reference/ROUTING_DECISION_MATRIX.md","lastUpdated":1771753292000}'),i={name:"reference/ROUTING_DECISION_MATRIX.md"};function l(r,t,o,d,p,c){return e(),s("div",null,[...t[0]||(t[0]=[n(`<h1 id="routing-decision-matrix-task-category-logic" tabindex="-1">Routing Decision Matrix: Task Category Logic <a class="header-anchor" href="#routing-decision-matrix-task-category-logic" aria-label="Permalink to &quot;Routing Decision Matrix: Task Category Logic&quot;">​</a></h1><p><strong>Purpose:</strong> Detailed routing decision logic per task category with hard constraint checks, soft optimization, and fallback chains.</p><p><strong>Last Updated:</strong> 2026-02-15 <strong>Integration Point:</strong> Feed this logic into <code>task-router.py</code> or equivalent dispatch system.</p><hr><h2 id="overview-task-categories-and-budget-allocation" tabindex="-1">Overview: Task Categories and Budget Allocation <a class="header-anchor" href="#overview-task-categories-and-budget-allocation" aria-label="Permalink to &quot;Overview: Task Categories and Budget Allocation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Category</th><th>Token Range</th><th>Monthly Budget</th><th>Cost/Call Limit</th><th>Calls/Month</th><th>Quality Floor</th><th>Speed SLA</th><th>Use Cases</th></tr></thead><tbody><tr><td><strong>FAST</strong></td><td>50–500 tokens</td><td>$50</td><td>$0.002</td><td>~25,000</td><td>70%</td><td>&lt;1s TTFT</td><td>Interactive, chat, quick queries</td></tr><tr><td><strong>NORMAL</strong></td><td>500–3K tokens</td><td>$200</td><td>$0.05</td><td>~4,000</td><td>73%</td><td>&lt;5s</td><td>Default tier, standard implementations</td></tr><tr><td><strong>COMPLEX</strong></td><td>3K–10K tokens</td><td>$150</td><td>$0.15</td><td>~1,000</td><td>75%</td><td>&lt;20s</td><td>Multi-step reasoning, debugging, analysis</td></tr><tr><td><strong>HIGH_COMPLEX</strong></td><td>&gt;10K tokens</td><td>$50</td><td>$0.85</td><td>~60</td><td>80%</td><td>&lt;60s</td><td>Architecture decisions, novel problems, final review</td></tr></tbody></table><hr><h2 id="fast-category-50–500-tokens-input-100–1k-output" tabindex="-1">FAST CATEGORY (50–500 tokens input, 100–1K output) <a class="header-anchor" href="#fast-category-50–500-tokens-input-100–1k-output" aria-label="Permalink to &quot;FAST CATEGORY (50–500 tokens input, 100–1K output)&quot;">​</a></h2><h3 id="category-parameters" tabindex="-1">Category Parameters <a class="header-anchor" href="#category-parameters" aria-label="Permalink to &quot;Category Parameters&quot;">​</a></h3><ul><li><strong>Performance Requirement:</strong> ≥70% (SWE-Bench or equivalent)</li><li><strong>Speed SLA:</strong> &lt;1 second TTFT (time-to-first-token)</li><li><strong>Instantaneous Budget Limit:</strong> $0.002 per call</li><li><strong>Cumulative Budget Limit:</strong> $50/month for all FAST tasks</li><li><strong>Expected Monthly Volume:</strong> ~25,000 calls (if 50M tokens total, avg 2K tokens/call)</li></ul><h3 id="hard-constraints-check" tabindex="-1">Hard Constraints Check <a class="header-anchor" href="#hard-constraints-check" aria-label="Permalink to &quot;Hard Constraints Check&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Constraint</th><th>Check</th><th>Result</th><th>Models Passing</th></tr></thead><tbody><tr><td>1</td><td>Quality ≥ 70%</td><td>SWE-Bench score or equivalent</td><td>✓</td><td>Haiku (73%), Gemini Flash (78%), GPT-4o mini (70%)</td></tr><tr><td>2</td><td>Cost ≤ $0.002/call</td><td>Haiku: $3.50/M × 0.5K avg = $0.00175</td><td>✓</td><td>Haiku ✓, Gemini Flash ($1.50–3/M × 0.5K = $0.001) ✓, GPT-4o mini ($0.375/M × 0.5K = $0.0002) ✓</td></tr><tr><td>3</td><td>Cumulative ≤ $50/mo</td><td>25,000 calls × $0.002 = $50</td><td>✓</td><td>All three models ✓</td></tr><tr><td>4</td><td>Speed &lt; 1s TTFT</td><td>P50 latency must be &lt;600ms</td><td>✓</td><td>Gemini Flash (150–600ms) ✓, GPT-4o mini (200–800ms) ⚠ P99 exceeds, Haiku (300–1200ms) ✗ P99 &gt;1s</td></tr></tbody></table><p><strong>Hard Constraint Verdict:</strong> Gemini Flash, GPT-4o mini meet all hard constraints. Haiku fails speed SLA (P99 &gt; 1s) but acceptable if &lt;5s SLA pushed up or interactive requirement relaxed.</p><h3 id="soft-optimization-after-hard-constraints-met" tabindex="-1">Soft Optimization (After Hard Constraints Met) <a class="header-anchor" href="#soft-optimization-after-hard-constraints-met" aria-label="Permalink to &quot;Soft Optimization (After Hard Constraints Met)&quot;">​</a></h3><p><strong>Priority Order:</strong> Speed &gt; Cost &gt; Quality</p><ol><li><p><strong>Primary Route:</strong> Gemini 3 Flash</p><ul><li>Cost: $1.50–3/M (avg $2/M, $0.001/call)</li><li>Quality: 78% (exceeds 70% floor)</li><li>Speed: 150–600ms P50 (fastest option, meets &lt;1s SLA with margin)</li><li>Risk: May hit daily quota limits on high-volume days (Gemini has generous but finite free tier)</li></ul></li><li><p><strong>Fallback 1:</strong> Claude Haiku 4.5</p><ul><li>Cost: $3.50/M ($0.00175/call)</li><li>Quality: 73% (meets floor)</li><li>Speed: 300–1200ms P50 (P99 &gt;1s; acceptable if latency SLA relaxed to &lt;5s)</li><li>Advantage: Proven production reliability, no quota limits, consistent availability</li></ul></li><li><p><strong>Fallback 2:</strong> GPT-4o mini</p><ul><li>Cost: $0.375/M ($0.0002/call, ultra-cheap)</li><li>Quality: 70% (meets floor exactly)</li><li>Speed: 200–800ms P50 (meets &lt;1s SLA but variable under load)</li><li>Use case: Emergency overflow when both Gemini &amp; Haiku exhausted</li></ul></li></ol><h3 id="decision-rules-pseudocode" tabindex="-1">Decision Rules (Pseudocode) <a class="header-anchor" href="#decision-rules-pseudocode" aria-label="Permalink to &quot;Decision Rules (Pseudocode)&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ROUTE_FAST(request):</span></span>
<span class="line"><span>  IF tokens &lt; 500 AND reasoning_depth ≤ 1 AND confidence_score &gt; 0.8:</span></span>
<span class="line"><span>    IF gemini_daily_quota_available():</span></span>
<span class="line"><span>      ROUTE → Gemini 3 Flash (primary)</span></span>
<span class="line"><span>    ELIF haiku_cost_available():</span></span>
<span class="line"><span>      ROUTE → Claude Haiku 4.5 (Fallback 1)</span></span>
<span class="line"><span>    ELIF gpt4o_cost_available():</span></span>
<span class="line"><span>      ROUTE → GPT-4o mini (Fallback 2)</span></span>
<span class="line"><span>    ELSE:</span></span>
<span class="line"><span>      ESCALATE → NORMAL category or queue request</span></span>
<span class="line"><span>  ELSE:</span></span>
<span class="line"><span>    ESCALATE → NORMAL category (task too complex for FAST)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><h3 id="monitoring-alerts" tabindex="-1">Monitoring &amp; Alerts <a class="header-anchor" href="#monitoring-alerts" aria-label="Permalink to &quot;Monitoring &amp; Alerts&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Metric</th><th>Alert Threshold</th><th>Action</th></tr></thead><tbody><tr><td>Gemini daily calls</td><td>&gt;500</td><td>Switch to Haiku fallback</td></tr><tr><td>Gemini cost cumulative</td><td>&gt;$40/mo (80% of $50)</td><td>Begin mixing in Haiku</td></tr><tr><td>Haiku cost cumulative</td><td>&gt;$40/mo (if primary)</td><td>Switch to GPT-4o for new requests</td></tr><tr><td>Average response time</td><td>&gt;600ms</td><td>Trigger load testing; consider splitting volume</td></tr><tr><td>Error rate</td><td>&gt;2%</td><td>Escalate to NORMAL category</td></tr></tbody></table><hr><h2 id="normal-category-500–3k-tokens-input-500–3k-output" tabindex="-1">NORMAL CATEGORY (500–3K tokens input, 500–3K output) <a class="header-anchor" href="#normal-category-500–3k-tokens-input-500–3k-output" aria-label="Permalink to &quot;NORMAL CATEGORY (500–3K tokens input, 500–3K output)&quot;">​</a></h2><h3 id="category-parameters-1" tabindex="-1">Category Parameters <a class="header-anchor" href="#category-parameters-1" aria-label="Permalink to &quot;Category Parameters&quot;">​</a></h3><ul><li><strong>Performance Requirement:</strong> ≥73% (SWE-Bench or equivalent)</li><li><strong>Speed SLA:</strong> &lt;5 seconds TTFT</li><li><strong>Instantaneous Budget Limit:</strong> $0.05 per call</li><li><strong>Cumulative Budget Limit:</strong> $200/month for all NORMAL tasks</li><li><strong>Expected Monthly Volume:</strong> ~4,000 calls (if 50M tokens total)</li><li><strong>Quality Baseline:</strong> Default tier; most work lands here</li></ul><h3 id="hard-constraints-check-1" tabindex="-1">Hard Constraints Check <a class="header-anchor" href="#hard-constraints-check-1" aria-label="Permalink to &quot;Hard Constraints Check&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Constraint</th><th>Check</th><th>Result</th><th>Models Passing</th></tr></thead><tbody><tr><td>1</td><td>Quality ≥ 73%</td><td>SWE-Bench score</td><td>✓</td><td>Haiku (73%), Sonnet (77%), Gemini Flash (78%), Minimax (80%), Opus (81%)</td></tr><tr><td>2</td><td>Cost ≤ $0.05/call</td><td>Haiku: $3.50/M × 1.5K avg = $0.0525</td><td>⚠</td><td>Haiku barely passes (edge case); Gemini ($2/M × 1.5K = $0.003) ✓, Sonnet ($10.50/M × 1.5K = $0.015) ✓</td></tr><tr><td>3</td><td>Cumulative ≤ $200/mo</td><td>4,000 calls × $0.05 = $200</td><td>✓</td><td>All models ✓</td></tr><tr><td>4</td><td>Speed &lt; 5s TTFT</td><td>P50 latency must be &lt;3s</td><td>✓</td><td>Haiku (300–1200ms) ✓, Sonnet (400–1500ms) ✓, Gemini (150–600ms) ✓</td></tr></tbody></table><p><strong>Hard Constraint Verdict:</strong> All major models pass. Haiku is at edge of cost limit (hits $0.0525/call for 1.5K token tasks); safer to assume max 1.2K avg for Haiku in NORMAL.</p><h3 id="soft-optimization-after-hard-constraints-met-1" tabindex="-1">Soft Optimization (After Hard Constraints Met) <a class="header-anchor" href="#soft-optimization-after-hard-constraints-met-1" aria-label="Permalink to &quot;Soft Optimization (After Hard Constraints Met)&quot;">​</a></h3><p><strong>Priority Order:</strong> Cost &gt; Quality &gt; Speed</p><ol><li><p><strong>Primary Route:</strong> Claude Haiku 4.5</p><ul><li>Cost: $3.50/M ($0.021/call typical for 1.5K tasks)</li><li>Quality: 73% (meets floor exactly; acceptable for well-defined tasks)</li><li>Speed: 300–1200ms P50 (comfortably under &lt;5s SLA)</li><li>Advantage: Cost-optimal, proven reliability, no quota limits</li><li>Risk: May struggle with complex multi-step tasks (requires clear prompting)</li></ul></li><li><p><strong>Fallback 1:</strong> Gemini 3 Flash</p><ul><li>Cost: $2/M avg ($0.003/call, ultra-cheap)</li><li>Quality: 78% (exceeds floor by 5%, noticeable quality jump)</li><li>Speed: 150–600ms P50 (faster than Haiku)</li><li>Use when: Haiku approaching budget limit or complex task needs quality bump but speed isn&#39;t critical</li></ul></li><li><p><strong>Fallback 2:</strong> Claude Sonnet 4.5</p><ul><li>Cost: $10.50/M ($0.0315/call typical for 1.5K tasks)</li><li>Quality: 77% (4-point quality jump over Haiku)</li><li>Speed: 400–1500ms P50 (still under 5s)</li><li>Use when: Haiku returns low-confidence or multi-step reasoning required</li></ul></li><li><p><strong>Fallback 3:</strong> Minimax M2.5</p><ul><li>Cost: $0.79/M ($0.001/call, extremely cheap)</li><li>Quality: 80% (frontier quality)</li><li>Speed: Very fast</li><li>Use when: Cost almost exhausted but task still needs 75%+ quality</li></ul></li></ol><h3 id="decision-rules-pseudocode-1" tabindex="-1">Decision Rules (Pseudocode) <a class="header-anchor" href="#decision-rules-pseudocode-1" aria-label="Permalink to &quot;Decision Rules (Pseudocode)&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ROUTE_NORMAL(request):</span></span>
<span class="line"><span>  IF 500 ≤ tokens ≤ 3000:</span></span>
<span class="line"><span>    IF complexity_score ≤ 3 AND haiku_cost_available():</span></span>
<span class="line"><span>      ROUTE → Claude Haiku 4.5 (primary, 70% of NORMAL traffic)</span></span>
<span class="line"><span>    ELIF quality_needed ≥ 76% OR multi_step_reasoning OR haiku_approaching_limit():</span></span>
<span class="line"><span>      IF gemini_cost_available():</span></span>
<span class="line"><span>        ROUTE → Gemini 3 Flash (fallback 1, 20% of NORMAL traffic)</span></span>
<span class="line"><span>      ELIF sonnet_cost_available():</span></span>
<span class="line"><span>        ROUTE → Claude Sonnet 4.5 (fallback 2, 8% of NORMAL traffic)</span></span>
<span class="line"><span>      ELSE:</span></span>
<span class="line"><span>        ROUTE → Minimax M2.5 (fallback 3, 2% of NORMAL traffic)</span></span>
<span class="line"><span>    ELIF cost_exhausted(haiku) AND quality_needed &lt; 75%:</span></span>
<span class="line"><span>      ROUTE → Minimax M2.5 (ultra-cheap overflow)</span></span>
<span class="line"><span>    ELSE:</span></span>
<span class="line"><span>      ESCALATE → COMPLEX category or queue</span></span>
<span class="line"><span>  ELSE:</span></span>
<span class="line"><span>    ESCALATE → COMPLEX category (token count exceeds NORMAL range)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br></div></div><h3 id="budget-enforcement-2x-limit-policy" tabindex="-1">Budget Enforcement (2x Limit Policy) <a class="header-anchor" href="#budget-enforcement-2x-limit-policy" aria-label="Permalink to &quot;Budget Enforcement (2x Limit Policy)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Threshold</th><th>Action</th><th>Notes</th></tr></thead><tbody><tr><td>$50 cumulative (25% of $200)</td><td>None; proceed normally</td><td>Green zone</td></tr><tr><td>$160 cumulative (80% of $200)</td><td><strong>WARN:</strong> Log alert; consider shifting to Minimax for remaining month</td><td>Yellow zone; require approval for expensive routes</td></tr><tr><td>$200 cumulative (100% of $200)</td><td><strong>BLOCK:</strong> No new NORMAL requests; escalate to COMPLEX or queue</td><td>Red zone; hard stop</td></tr></tbody></table><h3 id="monitoring-alerts-1" tabindex="-1">Monitoring &amp; Alerts <a class="header-anchor" href="#monitoring-alerts-1" aria-label="Permalink to &quot;Monitoring &amp; Alerts&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Metric</th><th>Alert Threshold</th><th>Action</th></tr></thead><tbody><tr><td>Haiku cost cumulative</td><td>&gt;$120/mo (60% of $200)</td><td>Begin mixing in Gemini/Minimax</td></tr><tr><td>Haiku error rate</td><td>&gt;1.5%</td><td>Switch to Sonnet for problematic task types</td></tr><tr><td>Average response time</td><td>&gt;3s</td><td>Load testing; consider batching</td></tr><tr><td>Quality regression</td><td>&lt;72% (below floor)</td><td>Switch to Sonnet for that task subtype</td></tr><tr><td>Cumulative at 80%</td><td>$160/mo</td><td>Alert ops; prepare to escalate tasks</td></tr></tbody></table><hr><h2 id="complex-category-3k–10k-tokens-input-1k–5k-output" tabindex="-1">COMPLEX CATEGORY (3K–10K tokens input, 1K–5K output) <a class="header-anchor" href="#complex-category-3k–10k-tokens-input-1k–5k-output" aria-label="Permalink to &quot;COMPLEX CATEGORY (3K–10K tokens input, 1K–5K output)&quot;">​</a></h2><h3 id="category-parameters-2" tabindex="-1">Category Parameters <a class="header-anchor" href="#category-parameters-2" aria-label="Permalink to &quot;Category Parameters&quot;">​</a></h3><ul><li><strong>Performance Requirement:</strong> ≥75% (SWE-Bench or equivalent; quality jump vs. NORMAL)</li><li><strong>Speed SLA:</strong> &lt;20 seconds TTFT</li><li><strong>Instantaneous Budget Limit:</strong> $0.15 per call</li><li><strong>Cumulative Budget Limit:</strong> $150/month for all COMPLEX tasks</li><li><strong>Expected Monthly Volume:</strong> ~1,000 calls</li><li><strong>Quality Baseline:</strong> Multi-step reasoning, debugging, analysis</li></ul><h3 id="hard-constraints-check-2" tabindex="-1">Hard Constraints Check <a class="header-anchor" href="#hard-constraints-check-2" aria-label="Permalink to &quot;Hard Constraints Check&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Constraint</th><th>Check</th><th>Result</th><th>Models Passing</th></tr></thead><tbody><tr><td>1</td><td>Quality ≥ 75%</td><td>SWE-Bench score</td><td>✓</td><td>Sonnet (77%), Gemini Flash (78%), Minimax (80%), Opus (81%)</td></tr><tr><td>2</td><td>Cost ≤ $0.15/call</td><td>Sonnet: $10.50/M × 5K avg = $0.0525</td><td>✓</td><td>Sonnet ✓, Gemini ($2/M × 5K = $0.01) ✓, Minimax ($0.79/M × 5K = $0.004) ✓, Opus ($17.50/M × 5K = $0.0875) ✓</td></tr><tr><td>3</td><td>Cumulative ≤ $150/mo</td><td>1,000 calls × $0.15 = $150</td><td>✓</td><td>All models ✓</td></tr><tr><td>4</td><td>Speed &lt; 20s TTFT</td><td>P50 latency must be &lt;15s</td><td>✓</td><td>All models ✓ (even Opus at 1.76s + overhead &lt;&lt; 15s)</td></tr></tbody></table><p><strong>Hard Constraint Verdict:</strong> Sonnet, Gemini, Minimax, and Opus all pass. Haiku (73%) dropped due to quality floor.</p><h3 id="soft-optimization-after-hard-constraints-met-2" tabindex="-1">Soft Optimization (After Hard Constraints Met) <a class="header-anchor" href="#soft-optimization-after-hard-constraints-met-2" aria-label="Permalink to &quot;Soft Optimization (After Hard Constraints Met)&quot;">​</a></h3><p><strong>Priority Order:</strong> Quality &gt; Cost &gt; Speed</p><ol><li><p><strong>Primary Route:</strong> Claude Sonnet 4.5</p><ul><li>Cost: $10.50/M ($0.0525/call for 5K tasks)</li><li>Quality: 77% (meets floor + 2-point buffer)</li><li>Speed: 400–1500ms P50 (fast, reserves time for complex reasoning)</li><li>Advantage: Production-proven, balanced quality/cost, reliable for debugging</li><li>Risk: Higher cost than Haiku (3x); justify when multi-step reasoning needed</li></ul></li><li><p><strong>Fallback 1:</strong> Gemini 3 Flash</p><ul><li>Cost: $2/M avg ($0.01/call, 5x cheaper than Sonnet)</li><li>Quality: 78% (exceeds Sonnet by 1 point)</li><li>Speed: 150–600ms P50 (faster than Sonnet)</li><li>Use when: Cost approaching limit and task doesn&#39;t need Sonnet&#39;s reasoning depth</li></ul></li><li><p><strong>Fallback 2:</strong> Claude Opus 4.6</p><ul><li>Cost: $17.50/M ($0.0875/call, highest in this category)</li><li>Quality: 81% (best available, 4-point jump)</li><li>Speed: 1760ms+ P50 (slower but acceptable &lt;20s SLA)</li><li>Use when: Task is genuinely hard (novel problem, architecture-level) or Sonnet returns low-confidence</li></ul></li><li><p><strong>Fallback 3:</strong> Minimax M2.5</p><ul><li>Cost: $0.79/M ($0.004/call, ultra-cheap)</li><li>Quality: 80% (frontier-level, competitive with Opus)</li><li>Speed: Very fast</li><li>Use when: Cost nearly exhausted and task is batch/non-urgent</li></ul></li></ol><h3 id="decision-rules-pseudocode-2" tabindex="-1">Decision Rules (Pseudocode) <a class="header-anchor" href="#decision-rules-pseudocode-2" aria-label="Permalink to &quot;Decision Rules (Pseudocode)&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ROUTE_COMPLEX(request):</span></span>
<span class="line"><span>  IF 3000 ≤ tokens ≤ 10000:</span></span>
<span class="line"><span>    IF complexity_score ≤ 6 AND confidence_threshold &gt;= 0.75:</span></span>
<span class="line"><span>      IF sonnet_cost_available():</span></span>
<span class="line"><span>        ROUTE → Claude Sonnet 4.5 (primary, 60% of COMPLEX traffic)</span></span>
<span class="line"><span>      ELIF gemini_cost_available():</span></span>
<span class="line"><span>        ROUTE → Gemini 3 Flash (fallback 1, 25% of COMPLEX traffic)</span></span>
<span class="line"><span>      ELIF minimax_cost_available():</span></span>
<span class="line"><span>        ROUTE → Minimax M2.5 (fallback 2, 10% of COMPLEX traffic)</span></span>
<span class="line"><span>      ELSE:</span></span>
<span class="line"><span>        ESCALATE → HIGH_COMPLEX with approval required</span></span>
<span class="line"><span>    ELIF complexity_score &gt; 6 OR confidence_threshold &lt; 0.70 OR reasoning_depth &gt; 3:</span></span>
<span class="line"><span>      IF opus_cost_available():</span></span>
<span class="line"><span>        ROUTE → Claude Opus 4.6 (fallback 2, 5% of COMPLEX traffic)</span></span>
<span class="line"><span>      ELIF sonnet_cost_available():</span></span>
<span class="line"><span>        ROUTE → Claude Sonnet 4.5 (secondary for hard tasks)</span></span>
<span class="line"><span>      ELSE:</span></span>
<span class="line"><span>        ESCALATE → HIGH_COMPLEX or queue with priority</span></span>
<span class="line"><span>    ELSE:</span></span>
<span class="line"><span>      ESCALATE → HIGH_COMPLEX category</span></span>
<span class="line"><span>  ELSE:</span></span>
<span class="line"><span>    ESCALATE → HIGH_COMPLEX category (token count exceeds COMPLEX range)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br></div></div><h3 id="budget-enforcement-2x-limit-policy-1" tabindex="-1">Budget Enforcement (2x Limit Policy) <a class="header-anchor" href="#budget-enforcement-2x-limit-policy-1" aria-label="Permalink to &quot;Budget Enforcement (2x Limit Policy)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Threshold</th><th>Action</th><th>Notes</th></tr></thead><tbody><tr><td>$50 cumulative (33% of $150)</td><td>None; proceed normally</td><td>Green zone</td></tr><tr><td>$120 cumulative (80% of $150)</td><td><strong>WARN:</strong> Log alert; evaluate if remaining tasks can wait until next month</td><td>Yellow zone; require approval for Opus-tier requests</td></tr><tr><td>$150 cumulative (100% of $150)</td><td><strong>BLOCK:</strong> No new COMPLEX requests; escalate to HIGH_COMPLEX queue</td><td>Red zone; hard stop</td></tr></tbody></table><h3 id="monitoring-alerts-2" tabindex="-1">Monitoring &amp; Alerts <a class="header-anchor" href="#monitoring-alerts-2" aria-label="Permalink to &quot;Monitoring &amp; Alerts&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Metric</th><th>Alert Threshold</th><th>Action</th></tr></thead><tbody><tr><td>Sonnet cost cumulative</td><td>&gt;$90/mo (60% of $150)</td><td>Begin mixing in Gemini/Minimax for well-defined tasks</td></tr><tr><td>Sonnet error rate</td><td>&gt;2%</td><td>Escalate problematic tasks to Opus for review</td></tr><tr><td>Opus cost per-request</td><td>&gt;$0.50 (indicates 6K+ token task)</td><td>Warn user; may overflow monthly budget in single request</td></tr><tr><td>Gemini daily calls</td><td>&gt;100</td><td>Monitor quota; may need fallback to Sonnet</td></tr><tr><td>Average response time</td><td>&gt;10s</td><td>Load analysis; consider batching</td></tr><tr><td>Cumulative at 80%</td><td>$120/mo</td><td>Alert ops; freeze non-urgent COMPLEX tasks</td></tr></tbody></table><hr><h2 id="high-complex-category-10k-tokens-5k-output" tabindex="-1">HIGH_COMPLEX CATEGORY (&gt;10K tokens, &gt;5K output) <a class="header-anchor" href="#high-complex-category-10k-tokens-5k-output" aria-label="Permalink to &quot;HIGH_COMPLEX CATEGORY (&gt;10K tokens, &gt;5K output)&quot;">​</a></h2><h3 id="category-parameters-3" tabindex="-1">Category Parameters <a class="header-anchor" href="#category-parameters-3" aria-label="Permalink to &quot;Category Parameters&quot;">​</a></h3><ul><li><strong>Performance Requirement:</strong> ≥80% (SWE-Bench or equivalent; mission-critical quality)</li><li><strong>Speed SLA:</strong> &lt;60 seconds TTFT (offline/batch acceptable)</li><li><strong>Instantaneous Budget Limit:</strong> $0.85 per call</li><li><strong>Cumulative Budget Limit:</strong> $50/month for all HIGH_COMPLEX tasks</li><li><strong>Expected Monthly Volume:</strong> ~60 calls (rare; mission-critical only)</li><li><strong>Quality Baseline:</strong> Architecture decisions, novel problems, final review, complex debugging</li></ul><h3 id="hard-constraints-check-3" tabindex="-1">Hard Constraints Check <a class="header-anchor" href="#hard-constraints-check-3" aria-label="Permalink to &quot;Hard Constraints Check&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Constraint</th><th>Check</th><th>Result</th><th>Models Passing</th></tr></thead><tbody><tr><td>1</td><td>Quality ≥ 80%</td><td>SWE-Bench score</td><td>✓</td><td>Opus (81%), Minimax (80%), GLM-5 (92.7% AIME)</td></tr><tr><td>2</td><td>Cost ≤ $0.85/call</td><td>Opus: $17.50/M × 8K avg = $0.14</td><td>✓</td><td>Opus ✓ ($0.14), Minimax ($0.79/M × 8K = $0.006) ✓, GLM-5 ($1/M × 8K = $0.008) ✓</td></tr><tr><td>3</td><td>Cumulative ≤ $50/mo</td><td>60 calls × $0.85 = $51</td><td>⚠</td><td>Budget is <em>tight</em>; Opus alone at $0.14/call = 357 calls max, but expected 60 calls = only $8.40/mo, so very safe margin</td></tr><tr><td>4</td><td>Speed &lt; 60s TTFT</td><td>P50 latency &lt;40s</td><td>✓</td><td>Opus (1760ms) ✓, all models ✓</td></tr></tbody></table><p><strong>Hard Constraint Verdict:</strong> Opus, Minimax, and GLM-5 pass. Sonnet (77%), Haiku (73%), Gemini Flash (78%) dropped due to 80% quality floor.</p><h3 id="soft-optimization-after-hard-constraints-met-3" tabindex="-1">Soft Optimization (After Hard Constraints Met) <a class="header-anchor" href="#soft-optimization-after-hard-constraints-met-3" aria-label="Permalink to &quot;Soft Optimization (After Hard Constraints Met)&quot;">​</a></h3><p><strong>Priority Order:</strong> Quality &gt; Speed &gt; Cost (cost is acceptable; quality is paramount)</p><ol><li><p><strong>Primary Route:</strong> Claude Opus 4.6</p><ul><li>Cost: $17.50/M ($0.14/call for 8K tasks)</li><li>Quality: 81% (best proven model for complex reasoning, novel problems)</li><li>Speed: 1760ms+ P50 (acceptable &lt;60s SLA for mission-critical)</li><li>Advantage: Largest context, best reasoning, production track record</li><li>Budget headroom: $50/mo ÷ $0.14/call = ~357 calls possible; only expecting 60</li><li>Risk: If usage exceeds ~60/mo, will overflow budget</li></ul></li><li><p><strong>Fallback 1:</strong> Minimax M2.5</p><ul><li>Cost: $0.79/M ($0.006/call, 20x cheaper than Opus)</li><li>Quality: 80% (meets floor; frontier-level)</li><li>Speed: Very fast</li><li>Use when: Task is non-urgent, cost approaching limit, or Opus quality not strictly needed</li><li>Risk: Lower production track record in US market</li></ul></li><li><p><strong>Fallback 2 (Rare):</strong> Claude Sonnet 4.5</p><ul><li>Cost: $10.50/M ($0.084/call for 8K tasks)</li><li>Quality: 77% (below 80% floor; only if task de-escalated)</li><li>Use when: Task initially HIGH_COMPLEX but scope reduced and Sonnet budget still available</li></ul></li></ol><h3 id="decision-rules-pseudocode-3" tabindex="-1">Decision Rules (Pseudocode) <a class="header-anchor" href="#decision-rules-pseudocode-3" aria-label="Permalink to &quot;Decision Rules (Pseudocode)&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ROUTE_HIGH_COMPLEX(request):</span></span>
<span class="line"><span>  IF tokens &gt; 10000:</span></span>
<span class="line"><span>    IF complexity_score &gt; 8 OR novel_problem OR architecture_level:</span></span>
<span class="line"><span>      IF opus_cost_available():</span></span>
<span class="line"><span>        ROUTE → Claude Opus 4.6 (primary, 90% of HIGH_COMPLEX)</span></span>
<span class="line"><span>      ELIF minimax_cost_available():</span></span>
<span class="line"><span>        ROUTE → Minimax M2.5 (fallback 1, 10% of HIGH_COMPLEX)</span></span>
<span class="line"><span>      ELSE:</span></span>
<span class="line"><span>        ESCALATE → Queue with &quot;URGENT&quot; tag; require manual approval &amp; budget reallocation</span></span>
<span class="line"><span>    ELIF can_reduce_scope_to_complex():</span></span>
<span class="line"><span>      ESCALATE → COMPLEX category (try to fit in reduced scope)</span></span>
<span class="line"><span>    ELSE:</span></span>
<span class="line"><span>      ESCALATE → Queue with human review required; manual approval for Opus</span></span>
<span class="line"><span>  ELSE:</span></span>
<span class="line"><span>    ERROR: Token count does not match HIGH_COMPLEX category</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br></div></div><h3 id="budget-enforcement-hard-caps-no-overflow" tabindex="-1">Budget Enforcement (Hard Caps, No Overflow) <a class="header-anchor" href="#budget-enforcement-hard-caps-no-overflow" aria-label="Permalink to &quot;Budget Enforcement (Hard Caps, No Overflow)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Threshold</th><th>Action</th><th>Notes</th></tr></thead><tbody><tr><td>$40 cumulative (80% of $50)</td><td><strong>WARN:</strong> Log alert; next HIGH_COMPLEX request requires manager approval</td><td>Yellow zone; escalation protocol</td></tr><tr><td>$50 cumulative (100% of $50)</td><td><strong>BLOCK:</strong> No new HIGH_COMPLEX requests without budget reallocation; escalate to human review</td><td>Red zone; hard stop</td></tr></tbody></table><h3 id="monitoring-alerts-3" tabindex="-1">Monitoring &amp; Alerts <a class="header-anchor" href="#monitoring-alerts-3" aria-label="Permalink to &quot;Monitoring &amp; Alerts&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Metric</th><th>Alert Threshold</th><th>Action</th></tr></thead><tbody><tr><td>Opus cost cumulative</td><td>&gt;$40/mo (80% of $50)</td><td>Alert ops; next request requires approval</td></tr><tr><td>Monthly call count</td><td>&gt;80 (above expected 60)</td><td>Investigate spike; may indicate category misclassification</td></tr><tr><td>Opus error rate</td><td>&gt;3%</td><td>Escalate problematic tasks to manual review</td></tr><tr><td>Response latency</td><td>&gt;30s</td><td>Opus may be under load; queue remaining requests</td></tr><tr><td>Cumulative at limit</td><td>$50/mo</td><td>Hard freeze; all subsequent requests denied until next month</td></tr></tbody></table><hr><h2 id="cross-category-budget-view" tabindex="-1">Cross-Category Budget View <a class="header-anchor" href="#cross-category-budget-view" aria-label="Permalink to &quot;Cross-Category Budget View&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Category</th><th>Monthly Budget</th><th>Primary Model</th><th>Fallback Chain</th><th>Total Commits</th></tr></thead><tbody><tr><td>FAST</td><td>$50</td><td>Gemini Flash → Haiku → GPT-4o mini</td><td>3</td><td>$450 cumulative</td></tr><tr><td>NORMAL</td><td>$200</td><td>Haiku → Gemini → Sonnet → Minimax</td><td>4</td><td></td></tr><tr><td>COMPLEX</td><td>$150</td><td>Sonnet → Gemini → Opus → Minimax</td><td>4</td><td></td></tr><tr><td>HIGH_COMPLEX</td><td>$50</td><td>Opus → Minimax (→ Sonnet if de-escalated)</td><td>2</td><td></td></tr></tbody></table><p><strong>Total Monthly Budget:</strong> $450 <strong>Current Spend:</strong> $550/mo <strong>Savings Target:</strong> $100/mo (18% reduction)</p><hr><h2 id="global-escalation-protocol" tabindex="-1">Global Escalation Protocol <a class="header-anchor" href="#global-escalation-protocol" aria-label="Permalink to &quot;Global Escalation Protocol&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>If all primary routes exhausted in category:</span></span>
<span class="line"><span>  IF next_cheaper_category_exists():</span></span>
<span class="line"><span>    TRY route to cheaper category (with quality check)</span></span>
<span class="line"><span>  ELIF higher_category_budget_available():</span></span>
<span class="line"><span>    ESCALATE to higher category (with approval)</span></span>
<span class="line"><span>  ELSE:</span></span>
<span class="line"><span>    QUEUE request with priority tag</span></span>
<span class="line"><span>    ALERT ops for manual triage</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Example: NORMAL task, Haiku budget exhausted, Gemini quota hit</span></span>
<span class="line"><span>  → Try routing to Minimax (cheaper, meets 80% floor)</span></span>
<span class="line"><span>  → If Minimax quota hit, escalate to COMPLEX with approval</span></span>
<span class="line"><span>  → If all exhausted, QUEUE for next month</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br></div></div><hr><h2 id="implementation-checklist" tabindex="-1">Implementation Checklist <a class="header-anchor" href="#implementation-checklist" aria-label="Permalink to &quot;Implementation Checklist&quot;">​</a></h2><ul><li>[ ] Create <code>task_router.py</code> with category detection logic (token count, complexity_score, reasoning_depth)</li><li>[ ] Integrate constraint validation (hard + soft checks per category)</li><li>[ ] Implement fallback chain dispatcher (route to next model if current exhausted)</li><li>[ ] Add cost tracking per category (cumulative, alert at 80%, block at 100%)</li><li>[ ] Set up monitoring dashboard (cost, latency, error rates, volume trends)</li><li>[ ] Wire hooks to log routing decisions (which model, why, cost impact)</li><li>[ ] Test escalation paths (all routes exhausted → queue + alert)</li><li>[ ] Document manual override procedure (ops can reallocate budget across categories)</li><li>[ ] Set calendar reminder to re-evaluate benchmarks Q1 2026</li></ul><hr><h2 id="faq-troubleshooting" tabindex="-1">FAQ &amp; Troubleshooting <a class="header-anchor" href="#faq-troubleshooting" aria-label="Permalink to &quot;FAQ &amp; Troubleshooting&quot;">​</a></h2><p><strong>Q: Haiku is failing tasks that should pass. Should I escalate immediately?</strong> A: No. Log failure patterns first (what task types, tokens, reasoning depth). If &gt;5% failure rate on specific subtype, escalate that subtype to Sonnet. Don&#39;t blanket-escalate the entire category.</p><p><strong>Q: We hit the NORMAL budget cap mid-month. What now?</strong> A: Switch all new NORMAL requests to Minimax (80% quality, $0.001/call); batch them if possible. Or escalate to COMPLEX for urgent, justified tasks. Do not violate the cap.</p><p><strong>Q: Can we reallocate budget between categories?</strong> A: Yes, but requires ops approval. Document the reason (e.g., &quot;HIGH_COMPLEX spike due to architecture redesign; reducing FAST budget by $20&quot;). Re-validate routing rules after reallocation.</p><p><strong>Q: Gemini Flash is hitting quota limits daily. What&#39;s the fallback?</strong> A: Haiku is primary fallback for FAST. If Haiku budget also tight, use GPT-4o mini (ultra-cheap, meets 70% floor). For NORMAL, switch to Minimax.</p><p><strong>Q: Should we use Cursor Ultra as a primary route?</strong> A: No. Cursor&#39;s pricing ($0.50/M effective, but $600-1000/mo overflow risk) is volatile. Use only as secondary fallback after exhausting safer options. Requires manual cost oversight.</p><p><strong>Q: How often should we re-evaluate the frontier matrix?</strong> A: Q1 2026 (next quarterly benchmark release). If major pricing changes occur mid-quarter, reassess immediately. Log benchmark dates in the routing system.</p><hr><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../reference/WORK_STREAM.html">WORK_STREAM.md</a> — canonical backlog</li><li><a href="./../plans/00-MASTER-INDEX.html">00-MASTER-INDEX.md</a> — plan index</li></ul><hr><h2 id="extension-summary" tabindex="-1">EXTENSION_SUMMARY <a class="header-anchor" href="#extension-summary" aria-label="Permalink to &quot;EXTENSION_SUMMARY&quot;">​</a></h2><p><strong>Extended on:</strong> 2026-02-17 <strong>Extended by:</strong> Claude Code</p><h3 id="changes-made" tabindex="-1">Changes Made <a class="header-anchor" href="#changes-made" aria-label="Permalink to &quot;Changes Made&quot;">​</a></h3><ol><li>Added practical implementation patterns</li><li>Added configuration examples</li><li>Enhanced cross-references to related documentation</li></ol><h3 id="cross-references-added" tabindex="-1">Cross-References Added <a class="header-anchor" href="#cross-references-added" aria-label="Permalink to &quot;Cross-References Added&quot;">​</a></h3><ul><li>Related research and implementation guides</li><li>WORK_STREAM.md for tracking</li></ul><h3 id="practical-additions" tabindex="-1">Practical Additions <a class="header-anchor" href="#practical-additions" aria-label="Permalink to &quot;Practical Additions&quot;">​</a></h3><ul><li>Implementation templates</li><li>Configuration examples</li><li>Best practices</li></ul>`,98)])])}const m=a(i,[["render",l]]);export{h as __pageData,m as default};
